    key: "refreshOptions",
    value: function refreshOptions(pageNumber) {
      var url = this.search == '' ? this.getURL : this.searchURL;
      if (pageNumber) {
        $(this.table).bootstrapTable('refreshOptions', { url: url, pageNumber: 1 });
      } else {
        $(this.table).bootstrapTable('refreshOptions', { url: url });
      }
    }
