				$("#" + this.columns.ownershipColumn + "2").parent().removeClass('disabled');
				$("#" + this.columns.ownershipColumn + "0").parent().addClass('disabled');

				$("#" + this.columns.ownershipColumn + this.editItem.ownership).click();
