        value: function getTerms(id, obj, direction, isall, thisorgID) {
            var _this4 = this;

            if (!thisorgID) {
                thisorgID = this.orgID;
            }
            $(obj).find("option").remove();
            if (isall) {
                $(obj).append("<option data-prev='0' data-next='0' value='0' >" + isall + "</option>");
            }

            var temp_url = apiURL + '/api/dashboard/term/page/' + thisorgID + '/termName/asc/' + termPerPage + '/1';
            if (direction != '' && direction !== 'n') {
                temp_url = apiURL + '/api/dashboard/term/' + thisorgID + '/termName/asc/' + termPerPage + '/1/termName/' + direction;
            }
            if (id && id != 0) {
                temp_url = apiURL + '/api/dashboard/term/get/' + thisorgID + '/' + id;
            }
            $.get(temp_url, function (dataIn) {
                for (var i = 0; i < dataIn.data.length; i++) {
                    var tmp = "<option data-prev='0' data-next='0' value='" + dataIn.data[i].termId + "' >" + dataIn.data[i].termName + "</option>";
                    if (direction == 'n') {
                        $(obj).append(tmp);
                    } else {
                        $(obj).prepend(tmp);
                    }
                }
                if (id != 0 || isall) {
                    $(obj).val(id).change();
                } else {
                    $(obj).change();
                }
            });
            if (isall) {
                $('body').off('change select', '#parentName', function (e) {
                    _this4.select_parentName();
                });
                $('body').on('change select', '#parentName', function (e) {
                    _this4.select_parentName();
                });
            }
        }
